ALTER TABLE FIDE_USUARIO_TB ADD CONSTRAINT FIDE_USUARIO_ESTADO_FK FOREIGN KEY (ID_ESTADO) REFERENCES FIDE_ESTADO_TB (ID_ESTADO);
ALTER TABLE FIDE_CLIENTE_TB ADD CONSTRAINT FIDE_CLIENTE_ESTADO_FK FOREIGN KEY (ID_ESTADO) REFERENCES FIDE_ESTADO_TB (ID_ESTADO);
ALTER TABLE FIDE_ACTIVO_TB ADD CONSTRAINT FIDE_ACTIVO_CLIENTE_FK FOREIGN KEY (ID_CLIENTE) REFERENCES FIDE_CLIENTE_TB (ID_CLIENTE);
ALTER TABLE FIDE_ACTIVO_TB ADD CONSTRAINT FIDE_ACTIVO_TIPO_FK FOREIGN KEY (ID_TIPO_ACTIVO) REFERENCES FIDE_TIPO_ACTIVO_TB (ID_TIPO_ACTIVO);
ALTER TABLE FIDE_ACTIVO_TB ADD CONSTRAINT FIDE_ACTIVO_RESPONSABLE_FK FOREIGN KEY (ID_USUARIO_RESPONSABLE) REFERENCES FIDE_USUARIO_TB (ID_USUARIO);
ALTER TABLE FIDE_ACTIVO_TB ADD CONSTRAINT FIDE_ACTIVO_ESTADO_FK FOREIGN KEY (ID_ESTADO) REFERENCES FIDE_ESTADO_TB (ID_ESTADO);
