ALTER TABLE FIDE_VULNERABILIDAD_TB ADD CONSTRAINT FIDE_VULN_CVE_FK FOREIGN KEY (ID_CVE) REFERENCES FIDE_CVE_TB (ID_CVE);
ALTER TABLE FIDE_VULNERABILIDAD_TB ADD CONSTRAINT FIDE_VULN_ESTADO_FK FOREIGN KEY (ID_ESTADO_VULNERABILIDAD) REFERENCES FIDE_ESTADO_VULNERABILIDAD_TB (ID_ESTADO_VULNERABILIDAD);
ALTER TABLE FIDE_VULNERABILIDAD_TB ADD CONSTRAINT FIDE_VULN_REVISOR_FK FOREIGN KEY (ID_USUARIO_REVISOR) REFERENCES FIDE_USUARIO_TB (ID_USUARIO);
ALTER TABLE FIDE_INCIDENTE_TB ADD CONSTRAINT FIDE_INCIDENTE_ACTIVO_FK FOREIGN KEY (ID_ACTIVO) REFERENCES FIDE_ACTIVO_TB (ID_ACTIVO);
