ALTER TABLE FIDE_INCIDENTE_TB ADD CONSTRAINT FIDE_INCIDENTE_TIPO_FK FOREIGN KEY (ID_TIPO_INCIDENTE) REFERENCES FIDE_TIPO_INCIDENTE_TB (ID_TIPO_INCIDENTE);
ALTER TABLE FIDE_INCIDENTE_TB ADD CONSTRAINT FIDE_INCIDENTE_SEVERIDAD_FK FOREIGN KEY (ID_SEVERIDAD) REFERENCES FIDE_SEVERIDAD_TB (ID_SEVERIDAD);
ALTER TABLE FIDE_INCIDENTE_TB ADD CONSTRAINT FIDE_INCIDENTE_ESTADO_FK FOREIGN KEY (ID_ESTADO_INCIDENTE) REFERENCES FIDE_ESTADO_INCIDENTE_TB (ID_ESTADO_INCIDENTE);
ALTER TABLE FIDE_INCIDENTE_TB ADD CONSTRAINT FIDE_INCIDENTE_REPORTA_FK FOREIGN KEY (ID_USUARIO_REPORTA) REFERENCES FIDE_USUARIO_TB (ID_USUARIO);
