ALTER TABLE FIDE_HISTORIAL_INCIDENTE_TB ADD CONSTRAINT FIDE_HISTORIAL_NUEVO_FK FOREIGN KEY (ID_ESTADO_NUEVO) REFERENCES FIDE_ESTADO_INCIDENTE_TB (ID_ESTADO_INCIDENTE);
