-- restricciones check de negocio
ALTER TABLE FIDE_SEVERIDAD_TB ADD CONSTRAINT FIDE_SEVERIDAD_CVSS_CK CHECK (CVSS_MINIMO BETWEEN 0 AND 10 AND CVSS_MAXIMO BETWEEN 0 AND 10 AND CVSS_MINIMO <= CVSS_MAXIMO);
ALTER TABLE FIDE_SEVERIDAD_TB ADD CONSTRAINT FIDE_SEVERIDAD_HORAS_CK CHECK (HORAS_RESPUESTA > 0 AND HORAS_RESOLUCION >= HORAS_RESPUESTA);
ALTER TABLE FIDE_ESTADO_INCIDENTE_TB ADD CONSTRAINT FIDE_ESTADO_INC_FINAL_CK CHECK (ES_FINAL IN ('S', 'N'));
ALTER TABLE FIDE_TRANSICION_ESTADO_TB ADD CONSTRAINT FIDE_TRANSICION_DISTINTO_CK CHECK (ID_ESTADO_ORIGEN <> ID_ESTADO_DESTINO);
ALTER TABLE FIDE_USUARIO_TB ADD CONSTRAINT FIDE_USUARIO_CAPACIDAD_CK CHECK (CAPACIDAD_MAXIMA BETWEEN 0 AND 20);
ALTER TABLE FIDE_USUARIO_TB ADD CONSTRAINT FIDE_USUARIO_CORREO_CK CHECK (REGEXP_LIKE(CORREO, '^[^@ ]+@[^@ ]+\.[^@ ]+$'));
ALTER TABLE FIDE_CLIENTE_TB ADD CONSTRAINT FIDE_CLIENTE_CORREO_CK CHECK (CORREO_CONTACTO IS NULL OR REGEXP_LIKE(CORREO_CONTACTO, '^[^@ ]+@[^@ ]+\.[^@ ]+$'));
ALTER TABLE FIDE_CVE_TB ADD CONSTRAINT FIDE_CVE_FORMATO_CK CHECK (REGEXP_LIKE(ID_CVE, '^CVE-[0-9]{4}-[0-9]{4,}$'));
ALTER TABLE FIDE_CVE_TB ADD CONSTRAINT FIDE_CVE_PUNTAJE_CK CHECK (PUNTAJE_CVSS BETWEEN 0 AND 10);
ALTER TABLE FIDE_CVE_TB ADD CONSTRAINT FIDE_CVE_VERSION_CK CHECK (VERSION_CVSS IN ('3.1', '4.0'));
ALTER TABLE FIDE_VULNERABILIDAD_TB ADD CONSTRAINT FIDE_VULN_FECHAS_CK CHECK (FECHA_REVISION IS NULL OR FECHA_REVISION >= FECHA_DETECCION);
ALTER TABLE FIDE_INCIDENTE_TB ADD CONSTRAINT FIDE_INCIDENTE_CIERRE_CK CHECK (FECHA_CIERRE IS NULL OR FECHA_CIERRE >= FECHA_REGISTRO);
ALTER TABLE FIDE_ALERTA_ESCALAMIENTO_TB ADD CONSTRAINT FIDE_ALERTA_TIPO_SLA_CK CHECK (TIPO_SLA IN ('RESPUESTA', 'RESOLUCION'));
ALTER TABLE FIDE_ALERTA_ESCALAMIENTO_TB ADD CONSTRAINT FIDE_ALERTA_NIVEL_CK CHECK (NIVEL_ESCALAMIENTO BETWEEN 1 AND 3);
ALTER TABLE FIDE_ALERTA_ESCALAMIENTO_TB ADD CONSTRAINT FIDE_ALERTA_ATENDIDA_CK CHECK (ATENDIDA IN ('S', 'N'));
ALTER TABLE FIDE_CONTROL_TB ADD CONSTRAINT FIDE_CONTROL_TIPO_CK CHECK (TIPO_CONTROL IN ('PREVENTIVO', 'DETECTIVO', 'CORRECTIVO'));

-- columna accion de auditoria en todas las tablas
ALTER TABLE FIDE_ESTADO_TB ADD CONSTRAINT FIDE_ESTADO_ACCION_CK CHECK (ACCION IN ('INSERT', 'UPDATE'));
