ALTER TABLE FIDE_VULNERABILIDAD_TB ADD CONSTRAINT FIDE_VULNERABILIDAD_ACCION_CK CHECK (ACCION IN ('INSERT', 'UPDATE'));
ALTER TABLE FIDE_INCIDENTE_TB ADD CONSTRAINT FIDE_INCIDENTE_ACCION_CK CHECK (ACCION IN ('INSERT', 'UPDATE'));
