ALTER TABLE FIDE_ALERTA_ESCALAMIENTO_TB ADD CONSTRAINT FIDE_ALERTA_ESCALAMIENTO_ACCION_CK CHECK (ACCION IN ('INSERT', 'UPDATE'));
